import { apiGet } from '../../lib/api/client.js'
import { renderTable } from '../../lib/output/table.js'
import { formatDate, formatBytes } from '../../lib/utils/format.js'
import chalk from 'chalk'

interface DeployEntry {
  id: string
  created_at: string
  file_count: number
  total_size: number
  triggered_by: string
  status: string
}

export default async function sitesDeploys(slug: string): Promise<void> {
  const data = await apiGet<{ deploys: DeployEntry[] }>(`/api/v1/sites/${slug}/deploys`, { authenticated: true })
  const rows = (data.deploys || []).map(d => ({
    id: chalk.dim(d.id.slice(0, 8)),
    date: formatDate(d.created_at),
    files: String(d.file_count),
    size: formatBytes(d.total_size),
    by: d.triggered_by,
    status: d.status === 'success' ? chalk.green('●') : d.status === 'failed' ? chalk.red('●') : chalk.yellow('○'),
  }))
  console.log(renderTable(rows, [
    { key: 'id', label: 'Deploy' },
    { key: 'date', label: 'Date' },
    { key: 'files', label: 'Files' },
    { key: 'size', label: 'Size' },
    { key: 'by', label: 'Triggered By' },
    { key: 'status', label: '' },
  ]))
}
